SELECT p.id, p.name, p.email, p.phone, p.created_at
FROM person p
WHERE p.workspace_id = #{workspaceId}
  AND p.id > #{afterId}
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
ORDER BY p.id
LIMIT #{limit}

SELECT c.id, c.name, c.website, c.phone, c.created_at
FROM company c
WHERE c.workspace_id = #{workspaceId}
  AND c.id > #{afterId}
ORDER BY c.id
LIMIT #{limit}

WITH ranked_matches AS ( SELECT p.id AS record_id, p.workspace_id AS record_workspace_id, p.name, c.name AS company_name, p.title, NULL AS website, NULL AS industry, pi.kind, pi.normalized_value, ROW_NUMBER() OVER ( PARTITION BY pi.kind, pi.normalized_value ORDER BY CASE WHEN p.workspace_id = #{workspaceId} THEN 0 ELSE 1 END, p.id ) AS match_rank FROM person_identity pi JOIN person p ON p.workspace_id = pi.workspace_id AND p.id = pi.person_id LEFT JOIN company c ON c.id = p.company_id AND WHERE pi.superseded_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL AND AND (
(pi.kind = #{key.kind} AND pi.normalized_value = #{key.normalizedValue})
) ) SELECT record_id, record_workspace_id, name, company_name, title, website, industry, kind, normalized_value FROM ranked_matches WHERE match_rank <= #{perKeyLimit} ORDER BY kind, normalized_value, record_id

WITH ranked_matches AS ( SELECT c.id AS record_id, c.workspace_id AS record_workspace_id, c.name, NULL AS company_name, NULL AS title, c.website, c.industry, ci.kind, ci.normalized_value, ROW_NUMBER() OVER ( PARTITION BY ci.kind, ci.normalized_value ORDER BY CASE WHEN c.workspace_id = #{workspaceId} THEN 0 ELSE 1 END, c.id ) AS match_rank FROM company_identity ci JOIN company c ON c.workspace_id = ci.workspace_id AND c.id = ci.company_id WHERE ci.superseded_at IS NULL AND AND (
(ci.kind = #{key.kind} AND ci.normalized_value = #{key.normalizedValue})
) ) SELECT record_id, record_workspace_id, name, company_name, title, website, industry, kind, normalized_value FROM ranked_matches WHERE match_rank <= #{perKeyLimit} ORDER BY kind, normalized_value, record_id

WITH requested_names AS (
SELECT #{key.normalizedName} AS normalized_name
), ranked_matches AS ( SELECT p.id AS record_id, p.workspace_id AS record_workspace_id, p.name, c.name AS company_name, p.title, NULL AS website, NULL AS industry, 'name' AS kind, requested_names.normalized_name AS normalized_value, ROW_NUMBER() OVER ( PARTITION BY requested_names.normalized_name ORDER BY CASE WHEN p.workspace_id = #{workspaceId} THEN 0 ELSE 1 END, p.id ) AS match_rank FROM requested_names JOIN person p ON p.normalized_name = requested_names.normalized_name LEFT JOIN company c ON c.id = p.company_id AND WHERE p.suspended_at IS NULL AND p.provision_ceased_at IS NULL AND ) SELECT record_id, record_workspace_id, name, company_name, title, website, industry, kind, normalized_value FROM ranked_matches WHERE match_rank <= #{perKeyLimit} ORDER BY normalized_value, record_id

WITH requested_names AS (
SELECT #{key.normalizedName} AS normalized_name
), ranked_matches AS ( SELECT c.id AS record_id, c.workspace_id AS record_workspace_id, c.name, NULL AS company_name, NULL AS title, c.website, c.industry, 'name' AS kind, requested_names.normalized_name AS normalized_value, ROW_NUMBER() OVER ( PARTITION BY requested_names.normalized_name ORDER BY CASE WHEN c.workspace_id = #{workspaceId} THEN 0 ELSE 1 END, c.id ) AS match_rank FROM requested_names JOIN company c ON c.normalized_name = requested_names.normalized_name WHERE ) SELECT record_id, record_workspace_id, name, company_name, title, website, industry, kind, normalized_value FROM ranked_matches WHERE match_rank <= #{perKeyLimit} ORDER BY normalized_value, record_id

mapper.update:
UPDATE person
SET normalized_name = #{normalizedName,jdbcType=VARCHAR}
WHERE workspace_id = #{workspaceId}
  AND id = #{personId}
  AND CAST(name AS BINARY) = CAST(#{rawName} AS BINARY)

UPDATE company
SET normalized_name = #{normalizedName,jdbcType=VARCHAR}
WHERE workspace_id = #{workspaceId}
  AND id = #{companyId}
  AND CAST(name AS BINARY) = CAST(#{rawName} AS BINARY)

UPDATE person_identity pi
JOIN person p
  ON p.workspace_id = pi.workspace_id
  AND p.id = pi.person_id
SET pi.superseded_at = #{supersededAt}
WHERE pi.workspace_id = #{workspaceId}
  AND pi.person_id = #{personId}
  AND pi.kind = 'email'
  AND pi.superseded_at IS NULL
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
  AND (
    (p.email IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(p.email AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND pi.normalized_value <> #{normalizedValue}

UPDATE person_identity pi
JOIN person p
  ON p.workspace_id = pi.workspace_id
  AND p.id = pi.person_id
SET pi.superseded_at = #{supersededAt}
WHERE pi.workspace_id = #{workspaceId}
  AND pi.person_id = #{personId}
  AND pi.kind = 'phone'
  AND pi.superseded_at IS NULL
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
  AND (
    (p.phone IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(p.phone AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND pi.normalized_value <> #{normalizedValue}

UPDATE company_identity ci
JOIN company c
  ON c.workspace_id = ci.workspace_id
  AND c.id = ci.company_id
SET ci.superseded_at = #{supersededAt}
WHERE ci.workspace_id = #{workspaceId}
  AND ci.company_id = #{companyId}
  AND ci.kind = 'domain'
  AND ci.superseded_at IS NULL
  AND (
    (c.website IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(c.website AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND ci.normalized_value <> #{normalizedValue}

UPDATE company_identity ci
JOIN company c
  ON c.workspace_id = ci.workspace_id
  AND c.id = ci.company_id
SET ci.superseded_at = #{supersededAt}
WHERE ci.workspace_id = #{workspaceId}
  AND ci.company_id = #{companyId}
  AND ci.kind = 'phone'
  AND ci.superseded_at IS NULL
  AND (
    (c.phone IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(c.phone AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND ci.normalized_value <> #{normalizedValue}
